// Ringgit Log: reads receipts, statements and route screenshots with Claude, for signed-in accounts.
//
// The website sends a job, { task: "extract" | "route" | "shot", ... } plus any pictures. This function
// checks the sign-in, counts the account's and the whole site's daily limits, builds the prompt with
// prompts.js (generated by build.sh from the app's own source, so it asks exactly what the app would)
// and streams Claude's reply back as plain text, followed by a NUL character and a status line
// such as {"stop":"end_turn","error":""}.
//
// Secrets (Supabase dashboard > Edge Functions > Secrets):
//   ANTHROPIC_API_KEY           required: reading stays off until it is set
//   ANTHROPIC_MODEL             optional, default claude-sonnet-5-5
//   READS_PER_ACCOUNT_PER_DAY   optional, default 40
//   READS_PER_DAY               optional, for the whole site, default 300
//   ALLOWED_ORIGINS             optional, comma-separated origins allowed to call this, default *
import { createClient } from "npm:@supabase/supabase-js@2.117.2";
import { extractPrompt, routePrompt, setToday, shotPrompt } from "./prompts.js";

const MODEL = Deno.env.get("ANTHROPIC_MODEL") || "claude-sonnet-5-5";
const PER_ACCOUNT = intEnv("READS_PER_ACCOUNT_PER_DAY", 40);
const PER_SITE = intEnv("READS_PER_DAY", 300);
const ORIGINS = (Deno.env.get("ALLOWED_ORIGINS") || "*").split(",").map((s) => s.trim()).filter(Boolean);
const END = "\u0000";
const TYPES = new Set(["mixed", "food", "travel", "parking", "shopping", "bills", "other"]);
const IMAGE_TYPES = new Set(["image/jpeg", "image/png", "image/webp", "image/gif"]);

function intEnv(name: string, fallback: number): number {
  const n = parseInt(Deno.env.get(name) || "", 10);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}
function cors(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin") || "";
  const allow = ORIGINS.includes("*") ? "*" : ORIGINS.includes(origin) ? origin : ORIGINS[0] || "";
  return {
    "Access-Control-Allow-Origin": allow,
    "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Expose-Headers": "x-reads-left",
    "Vary": "Origin",
  };
}
function reply(req: Request, body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...cors(req), "Content-Type": "application/json" } });
}
function adminClient() {
  let key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
  try {
    const keys = JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}");
    key = keys.default || Object.values(keys)[0] || key;
  } catch (_) { /* keep the legacy key */ }
  return createClient(Deno.env.get("SUPABASE_URL")!, key, { auth: { persistSession: false, autoRefreshToken: false } });
}

// ---------- checking what the website sent ----------
class BadRequest extends Error {}
function bad(message: string): never { throw new BadRequest(message); }
function text(v: unknown, max: number, name: string): string {
  if (v == null) return "";
  if (typeof v !== "string") bad(name + " must be text");
  const s = v.trim();
  if (s.length > max) bad(name + " is too long");
  return s;
}
function pictures(list: unknown, min: number, max: number) {
  const arr = list == null ? [] : list;
  if (!Array.isArray(arr)) bad("images must be a list");
  if (arr.length < min || arr.length > max) bad("wrong number of images");
  return arr.map((im) => {
    const type = String((im && im.type) || ""), data = String((im && im.data) || "");
    if (!IMAGE_TYPES.has(type)) bad("unsupported image type");
    if (!data || data.length > 7_000_000 || !/^[A-Za-z0-9+/]+={0,2}$/.test(data)) bad("bad image data");
    return { type: "image", source: { type: "base64", media_type: type, data } };
  });
}
function malaysiaToday(): string { return new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10); }
function pickToday(v: unknown): string {
  const today = malaysiaToday();
  if (typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v)) {
    const gap = Math.abs(Date.parse(v + "T00:00:00Z") - Date.parse(today + "T00:00:00Z"));
    if (gap <= 2 * 86400000) return v;   // the visitor's own date, unless their clock is far off
  }
  return today;
}
// deno-lint-ignore no-explicit-any
function buildJob(body: any): { content: unknown[]; maxTokens: number } {
  setToday(pickToday(body.today));
  if (body.task === "extract") {
    const ctx = body.ctx || {}, part = body.part || {};
    const type = String(ctx.type || "mixed");
    if (!TYPES.has(type)) bad("unknown type");
    const parkKind = ctx.parkKind === "office" || ctx.parkKind === "onsite" ? ctx.parkKind : "";
    const period = typeof part.period === "string" && /^\d{4}-\d{2}-\d{2}\.\.\d{4}-\d{2}-\d{2}$/.test(part.period) ? part.period : "";
    if (part.mode === "text") {
      pictures(body.images, 0, 0);
      const body_ = text(part.text, 14000, "text");
      if (!body_) bad("no text to read");
      const label = text(part.label, 80, "label");
      return { content: [{ type: "text", text: extractPrompt({ type, parkKind }, { mode: "text", text: body_, label, period }) }], maxTokens: 8192 };
    }
    if (part.mode === "image") {
      const pics = pictures(body.images, 1, 4);
      return { content: [...pics, { type: "text", text: extractPrompt({ type, parkKind }, { mode: "image", count: pics.length, period }) }], maxTokens: 8192 };
    }
    bad("unknown mode");
  }
  if (body.task === "route") {
    pictures(body.images, 0, 0);
    const from = text(body.from, 120, "from"), to = text(body.to, 120, "to");
    if (!from || !to) bad("from and to are needed");
    return { content: [{ type: "text", text: routePrompt(from, to) }], maxTokens: 3000 };
  }
  if (body.task === "shot") {
    const pics = pictures(body.images, 1, 3);
    return { content: [...pics, { type: "text", text: shotPrompt(pics.length) }], maxTokens: 2500 };
  }
  bad("unknown task");
}

// ---------- the request ----------
Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors(req) });
  if (req.method !== "POST") return reply(req, { code: "bad_request" }, 405);

  const token = (req.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "");
  if (!token) return reply(req, { code: "session_expired" }, 401);
  const admin = adminClient();
  const { data: auth, error: authError } = await admin.auth.getUser(token);
  const user = auth && auth.user;
  if (authError || !user) return reply(req, { code: "session_expired" }, 401);

  // deno-lint-ignore no-explicit-any
  let body: any;
  try { body = await req.json(); } catch (_) { return reply(req, { code: "bad_request" }, 400); }
  const apiKey = Deno.env.get("ANTHROPIC_API_KEY") || "";

  if (body && body.ping) {
    const { data: used } = await admin.rpc("ai_used_today", { p_user: user.id });
    return reply(req, { ready: !!apiKey, limit: PER_ACCOUNT, used: typeof used === "number" ? used : 0 });
  }
  if (!apiKey) return reply(req, { code: "not_configured" }, 503);

  let job;
  try { job = buildJob(body || {}); }
  catch (e) { return reply(req, { code: "bad_request", message: e instanceof BadRequest ? e.message : "" }, 400); }

  const { data: count, error: countError } = await admin.rpc("ai_take", { p_user: user.id, p_user_limit: PER_ACCOUNT, p_site_limit: PER_SITE });
  if (countError || typeof count !== "number") { console.error("ai_take", countError); return reply(req, { code: "unavailable" }, 503); }
  if (count === -1) return reply(req, { code: "daily_limit" }, 429);
  if (count === -2) return reply(req, { code: "site_limit" }, 429);
  const giveBack = () => admin.rpc("ai_refund", { p_user: user.id }).then(() => {}, () => {});

  let upstream: Response;
  try {
    upstream = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "x-api-key": apiKey, "anthropic-version": "2023-06-01", "content-type": "application/json" },
      body: JSON.stringify({ model: MODEL, max_tokens: job.maxTokens, stream: true, messages: [{ role: "user", content: job.content }] }),
    });
  } catch (e) {
    console.error("anthropic fetch", e);
    await giveBack();
    return reply(req, { code: "unavailable" }, 502);
  }
  if (!upstream.ok || !upstream.body) {
    const detail = await upstream.text().catch(() => "");
    console.error("anthropic", upstream.status, detail.slice(0, 500));
    await giveBack();
    const s = upstream.status;
    const code = s === 401 || s === 403 ? "not_configured"
      : s === 429 || s === 529 || s >= 500 ? "rate_limited"
      : s === 413 || /prompt is too long|too large/i.test(detail) ? "prompt_too_large"
      : /image/i.test(detail) ? "image_rejected"
      : "bad_request";
    return reply(req, { code }, s === 429 || s === 529 ? 429 : 502);
  }

  // Relay the text as it arrives; Server-Sent Events from Anthropic become plain text for the app.
  const reader = upstream.body.getReader();
  const stream = new ReadableStream({
    async start(controller) {
      const enc = new TextEncoder(), dec = new TextDecoder();
      let buf = "", stop = "", error = "", got = false;
      const handle = (block: string) => {
        const data = block.split("\n").filter((l) => l.startsWith("data:")).map((l) => l.slice(5).trim()).join("");
        if (!data) return;
        // deno-lint-ignore no-explicit-any
        let ev: any;
        try { ev = JSON.parse(data); } catch (_) { return; }
        if (ev.type === "content_block_delta" && ev.delta && ev.delta.type === "text_delta" && ev.delta.text) {
          got = true;
          controller.enqueue(enc.encode(String(ev.delta.text).replaceAll(END, "")));
        } else if (ev.type === "message_delta" && ev.delta && ev.delta.stop_reason) {
          stop = ev.delta.stop_reason;
        } else if (ev.type === "error") {
          error = ev.error && ev.error.type === "overloaded_error" ? "rate_limited" : "unavailable";
        }
      };
      try {
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          buf += dec.decode(value, { stream: true }).replace(/\r\n/g, "\n");
          let i;
          while ((i = buf.indexOf("\n\n")) >= 0) { handle(buf.slice(0, i)); buf = buf.slice(i + 2); }
        }
        if (buf.trim()) handle(buf);
      } catch (e) {
        console.error("stream", e);
        error = error || "unavailable";
      }
      if (stop === "refusal") error = "refused";
      if (!got && error && error !== "refused") await giveBack();   // nothing was read because of a fault on Claude's side
      controller.enqueue(enc.encode(END + JSON.stringify({ stop, error })));
      controller.close();
    },
    cancel() { reader.cancel().catch(() => {}); },
  });
  return new Response(stream, {
    headers: { ...cors(req), "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store", "x-reads-left": String(Math.max(0, PER_ACCOUNT - count)) },
  });
});
